const $=id=>document.getElementById(id);let items=[],uploads=[],originalBytes,urls=[];function url(blob){let u=URL.createObjectURL(blob);urls.push(u);return u}function cleanup(){urls.forEach(URL.revokeObjectURL);urls=[]}function status(s){$('status').textContent=s}function blobOf(c){return new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(Error('Image conversion failed')),'image/png'))}
async function decode(bytes,name,marked=false){let blob=new Blob([bytes]),u=url(blob),im=new Image();im.src=u;await im.decode();let c=document.createElement('canvas');let ratio=Math.min(1,2200/Math.max(im.width,im.height));c.width=Math.round(im.width*ratio);c.height=Math.round(im.height*ratio);let ctx=c.getContext('2d');ctx.drawImage(im,0,0,c.width,c.height);if(marked){let h=Math.max(24,Math.round(c.height*.035));ctx.fillStyle='rgba(23,55,40,.8)';ctx.fillRect(0,c.height-h,c.width,h);ctx.fillStyle='white';ctx.font=`bold ${Math.round(h*.6)}px sans-serif`;ctx.fillText('TEST REPLACEMENT',15,c.height-h*.22)}let small=document.createElement('canvas');small.width=32;small.height=32;let s=small.getContext('2d',{willReadFrequently:true});s.drawImage(c,0,0,32,32);let feature=PhotoMatch.feature(s.getImageData(0,0,32,32).data);let png=await blobOf(c);return {feature,preview:url(png),png:await png.arrayBuffer(),name}}
$('doc').onchange=()=>{$('docLabel').textContent=$('doc').files[0]?.name||'Choose a DOCX'};$('photos').onchange=()=>{$('photoLabel').textContent=$('photos').files.length+' photos selected'};
function tally(){let counts={matched:0,missing:0,review:0},used=new Set();items.forEach(p=>{counts[p.status]++;if(p.index!==null)used.add(p.index)});$('summary').textContent=`${counts.matched} matched · ${counts.missing} missing · ${counts.review} to review`;$('download').disabled=counts.review>0;$('ignoredSummary').textContent=`${uploads.length-used.size} unused uploads`;$('ignored').replaceChildren();uploads.forEach((u,i)=>{if(!used.has(i)){let im=document.createElement('img');im.src=u.preview;im.alt=u.name;im.title=u.name;$('ignored').append(im)}})}
function render(){let cards=$('cards');cards.replaceChildren();items.forEach((p,i)=>{let card=document.createElement('article');card.className='card';let h=document.createElement('h3');h.textContent=`Photo ${i+1}${p.part!=='word/document.xml'?' · '+p.part.split('/').pop():''}`;let badge=document.createElement('div');badge.className='badge '+p.status;let pair=document.createElement('div');pair.className='pair';let left=document.createElement('div'),right=document.createElement('div');left.innerHTML='<label>IN THE DOCUMENT</label>';right.innerHTML='<label>REPLACEMENT</label>';let a=document.createElement('img'),b=document.createElement('img');a.src=p.preview;a.alt='Original document photo '+(i+1);b.alt='Selected replacement';left.append(a);right.append(b);pair.append(left,right);let sel=document.createElement('select');sel.setAttribute('aria-label','Replacement for photo '+(i+1));sel.add(new Option('Choose a photo — review required','review'));sel.add(new Option('Not found — replace with text','missing'));let top=PhotoMatch.rank(p.feature,uploads);top.forEach(r=>sel.add(new Option(`${uploads[r.index].name} · distance ${r.distance.toFixed(3)}`,String(r.index))));function update(){sel.value=p.index===null?p.status:String(p.index);badge.textContent=p.status==='matched'?'MATCHED':p.status==='missing'?'NOT FOUND':'REVIEW REQUIRED';badge.className='badge '+p.status;if(p.index!==null){b.src=uploads[p.index].preview;b.style.visibility='visible'}else{b.removeAttribute('src');b.style.visibility='hidden'}}sel.onchange=()=>{if(sel.value==='review'||sel.value==='missing'){p.status=sel.value;p.index=null}else{p.status='matched';p.index=Number(sel.value)}update();tally()};update();card.append(h,badge,pair,sel);cards.append(card)});tally()}
$('scan').onclick=async()=>{if(!$('doc').files.length||!$('photos').files.length){status('Choose a DOCX and at least one photo.');return}let btn=$('scan');btn.disabled=true;$('results').hidden=true;cleanup();try{status('Reading the document…');originalBytes=await $('doc').files[0].arrayBuffer();let zip=await JSZip.loadAsync(originalBytes);if(!zip.file('word/document.xml'))throw Error('This file is not a valid Word DOCX.');items=await PhotoMatch.scan(zip,decode,$('extra').checked);if(!items.length)throw Error('No supported embedded photos were found.');uploads=[];for(let f of $('photos').files){status(`Reading upload ${uploads.length+1} of ${$('photos').files.length}…`);uploads.push(await decode(await f.arrayBuffer(),f.name,$('watermark').checked))}items.forEach(p=>Object.assign(p,PhotoMatch.decide(PhotoMatch.rank(p.feature,uploads),Number($('tolerance').value))));render();$('results').hidden=false;status('Scan complete. Review the proposed replacements below.');$('results').scrollIntoView({behavior:'smooth',block:'start'})}catch(e){status('Error: '+e.message)}finally{btn.disabled=false}};
$('download').onclick=async()=>{let btn=$('download');btn.disabled=true;try{status('Building your updated document…');let zip=await JSZip.loadAsync(originalBytes);let out=await PhotoMatch.exportDoc(zip,items,uploads);let a=document.createElement('a');a.href=url(new Blob([out],{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'}));a.download=$('doc').files[0].name.replace(/\.docx$/i,'')+'-updated.docx';a.click();status('Updated DOCX downloaded.')}catch(e){status('Error: '+e.message)}finally{tally()}};
